package net.civeira.phylax.feature.observe.observedslo.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSloKindOptions;

class KindVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property kind of observed slo ")
  void test_kind_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom("_AVAILABILITY_"));
    Assertions.assertEquals(ObservedSloKindOptions.AVAILABILITY,
        KindVO.tryFrom("AVAILABILITY").getKind());
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom(null));
    Assertions.assertEquals(ObservedSloKindOptions.AVAILABILITY,
        KindVO.from(ObservedSloKindOptions.AVAILABILITY).getKind());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedSloKindOptions.AVAILABILITY + "]",
        KindVO.from(ObservedSloKindOptions.AVAILABILITY).toString());
  }
}
